Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
nvme-pci: handle changing device dma map requirements

The initial state of dma_needs_unmap may be false, but change to true
while mapping the data iterator. Enabling swiotlb is one such case that
can change the result. The nvme driver needs to save the mapped dma
vectors to be unmapped later, so allocate as needed during iteration
rather than assume it was always allocated at the beginning. This fixes
a NULL dereference from accessing an uninitialized dma_vecs when the
device dma unmapping requirements change mid-iteration.

Fixes: b8b7570a7ec8 ("nvme-pci: fix dma unmapping when using PRPs and not using the IOVA mapping")
Link: https://lore.kernel.org/linux-nvme/20260202125738.1194899-1-pradeep.pragallapati@oss.qualcomm.com/
Reported-by: Pradeep P V K <pradeep.pragallapati@oss.qualcomm.com>
Reviewed-by: Christoph Hellwig <hch@lst.de>
Signed-off-by: Keith Busch <kbusch@kernel.org>

Here is the root cause:
The initial state of `dma_need_unmap()` may be false when `nvme_pci_setup_data_prp()` allocates the `dma_vecs` array, so it skips allocation. However, later during iteration in `nvme_pci_prp_iter_next()`, the device's DMA mapping requirement changes (e.g., swiotlb enables), making `dma_need_unmap()` return true. The code then attempts to save mappings into `iod->dma_vecs` without confirming the array was allocated, leading to a NULL pointer dereference.

Here is the patch:

+static bool nvme_pci_prp_save_mapping(struct request *req,
+				      struct device *dma_dev,
+				      struct blk_dma_iter *iter)
+{
+	struct nvme_iod *iod = blk_mq_rq_to_pdu(req);
+
+	if (dma_use_iova(&iod->dma_state) || !dma_need_unmap(dma_dev))
+		return true;
+
+	if (!iod->nr_dma_vecs) {
+		struct nvme_queue *nvmeq = req->mq_hctx->driver_data;
+
+		iod->dma_vecs = mempool_alloc(nvmeq->dev->dmavec_mempool,
+				GFP_ATOMIC);
+		if (!iod->dma_vecs) {
+			iter->status = BLK_STS_RESOURCE;
+			return false;
+		}
+	}
+
+	iod->dma_vecs[iod->nr_dma_vecs].addr = iter->addr;
+	iod->dma_vecs[iod->nr_dma_vecs].len = iter->len;
+	iod->nr_dma_vecs++;
+	return true;
+}
+
 static bool nvme_pci_prp_iter_next(struct request *req, struct device *dma_dev,
 		struct blk_dma_iter *iter)
 {
 	struct nvme_iod *iod = blk_mq_rq_to_pdu(req);

 	if (iter->len)
 		return true;
 	if (!blk_rq_dma_map_iter_next(req, dma_dev, &iod->dma_state, iter))
 		return false;
-	if (!dma_use_iova(&iod->dma_state) && dma_need_unmap(dma_dev)) {
-		iod->dma_vecs[iod->nr_dma_vecs].addr = iter->addr;
-		iod->dma_vecs[iod->nr_dma_vecs].len = iter->len;
-		iod->nr_dma_vecs++;
-	}
-	return true;
+	return nvme_pci_prp_save_mapping(req, dma_dev, iter);
 }

 static blk_status_t nvme_pci_setup_data_prp(struct request *req,
 		struct blk_dma_iter *iter)
 {
 	struct nvme_iod *iod = blk_mq_rq_to_pdu(req);
 	struct nvme_queue *nvmeq = req->mq_hctx->driver_data;
 	unsigned int length = blk_rq_payload_bytes(req);
 	dma_addr_t prp1_dma, prp2_dma = 0;
 	unsigned int prp_len, i;
 	__le64 *prp_list;

-	if (!dma_use_iova(&iod->dma_state) && dma_need_unmap(nvmeq->dev->dev)) {
-		iod->dma_vecs = mempool_alloc(nvmeq->dev->dmavec_mempool,
-				GFP_ATOMIC);
-		if (!iod->dma_vecs)
-			return BLK_STS_RESOURCE;
-		iod->dma_vecs[0].addr = iter->addr;
-		iod->dma_vecs[0].len = iter->len;
-		iod->nr_dma_vecs = 1;
-	}
+	if (!nvme_pci_prp_save_mapping(req, nvmeq->dev->dev, iter))
+		return iter->status;

 	/*
 	 * PRP1 always points to the start of the DMA transfers.
 	 *
 	 * This is the only PRP (except for the list entries) that could be
 	 * non-aligned.
 	 */
 	prp1_dma = iter->addr;
 	prp_len = min(length, NVME_CTRL_PAGE_SIZE -
 			(iter->addr & (NVME_CTRL_PAGE_SIZE - 1)));
 	iod->total_len += prp_len;
 	iter->addr += prp_len;
 	iter->len -= prp_len;
 	length -= prp_len;
 	if (!length)
 		goto done;

 	if (!nvme_pci_prp_iter_next(req, nvmeq->dev->dev, iter)) {
 		if (WARN_ON_ONCE(!iter->status))
 			goto bad_sgl;
 		goto done;
 	}

 	/*
 	 * PRP2 is usually a list, but can point to data if all data to be
 	 * transferred fits into PRP1 + PRP2:
 	 */
 	if (length <= NVME_CTRL_PAGE_SIZE) {
 		prp2_dma = iter->addr;
 		iod->total_len += length;
 		goto done;
 	}

 	if (DIV_ROUND_UP(length, NVME_CTRL_PAGE_SIZE) <=
 	    NVME_SMALL_POOL_SIZE / sizeof(__le64))
 		iod->flags |= IOD_SMALL_DESCRIPTOR;

 	prp_list = dma_pool_alloc(nvme_dma_pool(nvmeq, iod), GFP_ATOMIC,
 			&prp2_dma);
 	if (!prp_list) {
 		iter->status = BLK_STS_RESOURCE;
 		goto done;
 	}
 	iod->descriptors[iod->nr_descriptors++] = prp_list;

 	i = 0;
 	for (;;) {
 		prp_list[i++] = cpu_to_le64(iter->addr);
 		prp_len = min(length, NVME_CTRL_PAGE_SIZE);
 		if (WARN_ON_ONCE(iter->len < prp_len))
 			goto bad_sgl;

 		iod->total_len += prp_len;
 		iter->addr += prp_len;
 		iter->len -= prp_len;
 		length -= prp_len;
 		if (!length)
 			break;

 		if (!nvme_pci_prp_iter_next(req, nvmeq->dev->dev, iter)) {
 			if (WARN_ON_ONCE(!iter->status))
 				goto bad_sgl;
 			goto done;
 		}

 		/*
 		 * If we've filled the entire descriptor, allocate a new that is
 		 * pointed to be the last entry in the previous PRP list.  To
 		 * accommodate for that move the last actual entry to the new
 		 * descriptor.
 		 */
 		if (i == NVME_CTRL_PAGE_SIZE >> 3) {
 			__le64 *old_prp_list = prp_list;
 			dma_addr_t prp_list_dma;

 			prp_list = dma_pool_alloc(nvmeq->descriptor_pools.large,
 					GFP_ATOMIC, &prp_list_dma);
 			if (!prp_list) {
 				iter->status = BLK_STS_RESOURCE;
 				goto done;
 			}
 			iod->descriptors[iod->nr_descriptors++] = prp_list;

 			prp_list[0] = old_prp_list[i - 1];
 			old_prp_list[i - 1] = cpu_to_le64(prp_list_dma);
 			i = 1;
 		}
 	}

 done:
 	/*
 	 * nvme_unmap_data uses the DPT field in the SQE to tear down the
 	 * mapping, so initialize it even for failures.
 	 */
 	iod->cmd.common.dptr.prp1 = cpu_to_le64(prp1_dma);
 	iod->cmd.common.dptr.prp2 = cpu_to_le64(prp2_dma);
 	if (unlikely(iter->status))
 		nvme_unmap_data(req);
 	return iter->status;

 bad_sgl:
 	dev_err_once(nvmeq->dev->dev,
 		"Incorrectly formed request for payload:%d nents:%d\n",
 		blk_rq_payload_bytes(req), blk_rq_nr_phys_segments(req));
 	return BLK_STS_IOERR;
 }


 static blk_status_t nvme_prep_rq(struct request *req)
 {
 	struct nvme_iod *iod = blk_mq_rq_to_pdu(req);
 	blk_status_t ret;

 	iod->flags = 0;
 	iod->nr_descriptors = 0;
 	iod->total_len = 0;
 	iod->meta_total_len = 0;
+	iod->nr_dma_vecs = 0;

 	ret = nvme_setup_cmd(req->q->queuedata, req);
 	if (ret)
 		return ret;

 	if (blk_rq_nr_phys_segments(req)) {
 		ret = nvme_map_data(req);
 		if (ret)
 			goto out_free_cmd;
 	}

 	if (blk_integrity_rq(req)) {
 		ret = nvme_map_metadata(req);
 		if (ret)
 			goto out_unmap_data;
 	}

 	nvme_start_request(req);
 	return BLK_STS_OK;
 out_unmap_data:
 	if (blk_rq_nr_phys_segments(req))
 		nvme_unmap_data(req);
 out_free_cmd:
 	nvme_cleanup_cmd(req);
 	return ret;
 }



